<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import DataChart from '@/components/DataChart.vue'
import { getComparison, getExperiment } from '@/api/ml'
import type { Experiment } from '@/types/ml'
const rows=ref<any[]>([]), selected=ref<Experiment>(), loading=ref(false)
const maeOption=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'category',data:rows.value.map(r=>r.model_type.toUpperCase())},yAxis:{type:'value',name:'MAE (m/s)'},series:[{type:'bar',data:rows.value.map(r=>r.mae),itemStyle:{color:'#397fa5'}}]}))
const rmseOption=computed(()=>({tooltip:{trigger:'axis'},xAxis:{type:'category',data:rows.value.map(r=>r.model_type.toUpperCase())},yAxis:{type:'value',name:'RMSE (m/s)'},series:[{type:'bar',data:rows.value.map(r=>r.rmse),itemStyle:{color:'#d28745'}}]}))
const comparisonOption=computed(()=>{const p=selected.value?.metrics.test?.points??[];return{tooltip:{trigger:'axis'},legend:{data:['真实风速','预测风速']},xAxis:{type:'category',data:p.map(v=>v.target_time.slice(0,10)),axisLabel:{show:false}},yAxis:{type:'value',name:'m/s'},series:[{name:'真实风速',type:'line',showSymbol:false,data:p.map(v=>v.actual)},{name:'预测风速',type:'line',showSymbol:false,data:p.map(v=>v.predicted)}]}})
const errorOption=computed(()=>{const p=selected.value?.metrics.test?.points??[];const bins=Array.from({length:13},(_,i)=>i-6);return{xAxis:{type:'category',data:bins.map(v=>`${v}~${v+1}`)},yAxis:{type:'value',name:'样本'},series:[{type:'bar',data:bins.map(v=>p.filter(x=>x.error>=v&&x.error<v+1).length)}]}})
async function select(row:any){selected.value=await getExperiment(row.experiment_id)}
function exportPng(){const canvas=document.querySelector('.page-stack canvas') as HTMLCanvasElement|null;if(!canvas)return;const link=document.createElement('a');link.download='model-evaluation.png';link.href=canvas.toDataURL('image/png');link.click()}
onMounted(async()=>{loading.value=true;rows.value=await getComparison();if(rows.value.length)await select(rows.value[0]);loading.value=false})
</script>
<template><section v-loading="loading" class="page-stack"><div class="page-heading"><div><h2>预测性能评估</h2><p>独立事件测试集 · 所有指标来自已保存模型</p></div><el-button @click="exportPng">导出图表 PNG</el-button></div><el-alert title="公平比较口径" description="测试集未参与训练或参数选择。第三阶段四种模型使用相同 722 个样本；未来 SAF-Net 只有在 ERA5 覆盖和样本集合相同时才能直接公平比较。表格始终显示各模型实际测试样本数。" type="info" :closable="false" show-icon/><div class="chart-grid"><el-card shadow="never"><DataChart :option="maeOption" label="模型 MAE 对比"/></el-card><el-card shadow="never"><DataChart :option="rmseOption" label="模型 RMSE 对比"/></el-card></div><el-card shadow="never"><el-table :data="rows" @row-click="select"><el-table-column prop="name" label="实验"/><el-table-column prop="model_type" label="模型"/><el-table-column prop="sample_count" label="测试样本"/><el-table-column label="MAE"><template #default="{row}">{{row.mae.toFixed(3)}}</template></el-table-column><el-table-column label="RMSE"><template #default="{row}">{{row.rmse.toFixed(3)}}</template></el-table-column><el-table-column label="Bias"><template #default="{row}">{{row.bias.toFixed(3)}}</template></el-table-column><el-table-column label="相对 Persistence"><template #default="{row}">{{row.improvement_pct==null?'不可计算':row.improvement_pct.toFixed(2)+'%'}}</template></el-table-column></el-table></el-card><template v-if="selected"><div class="chart-grid"><el-card shadow="never"><DataChart :option="comparisonOption" label="真实与预测风速对比"/></el-card><el-card shadow="never"><DataChart :option="errorOption" label="预测误差分布"/></el-card></div></template></section></template>
